import{_ as i,C as o,c as n,o as r,aa as s,G as t}from"./chunks/framework.Cn7WEiMX.js";const p="/assets/item1.D7tECfWH.png",d="/assets/item2.CyapwR1H.png",M=JSON.parse('{"title":"🔌 其他插件","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/MMOInventory/compatibility/other-plugins.md","filePath":"wiki/MMOInventory/compatibility/other-plugins.md"}'),l={name:"wiki/MMOInventory/compatibility/other-plugins.md"};function m(_,e,g,u,f,h){const a=o("NolebaseGitContributors"),c=o("NolebaseGitChangelog");return r(),n("div",null,[e[0]||(e[0]=s('<h1 id="🔌-其他插件" tabindex="-1">🔌 其他插件 <a class="header-anchor" href="#🔌-其他插件" aria-label="Permalink to &quot;🔌 其他插件&quot;">​</a></h1> <p>MMOInventory 的一大特色就是内置了对其他物品插件的支持。它可以从 LoreAttributesRecoded、Oraxen 或 Nexo 这样的插件中读取属性，但也只能通过固定模板匹配描述里的内容。例如，如果物品描述里有 <code>&amp;c剑</code>，那么 MMOInventory 可以检测它，让槽位限制正常生效。</p> <p>这是一种“伪物品类型”，虽然没有在 MMOItems 这样的插件中经过注册，但仍然可以归入特定分类（通过识别特定格式的描述判断其类型）。</p> <p><code>loretag{tag=&quot;&amp;c戒指&quot;}</code> 之类的条件只会允许描述中完全包含 <code>&amp;c戒指</code> 的物品放入。这类槽位限制完全兼容基本的颜色代码。<code>loretag{tag=&quot;&amp;c剑&quot;;check=&quot;EQUALS&quot;}</code> 的效果基本相同。如下物品包含一行 <code>&amp;c戒指</code>，因此适用槽位限制条件。</p> <figure><img src="'+p+'" alt="" tabindex="0"><figcaption></figcaption></figure> <p><code>loretag{tag=&quot;&amp;c描述&quot;;check=CONTAINS}</code> 检测物品的描述中是否含有 <code>&amp;c戒指</code>。如下物品包含一行 <code>&amp;c戒指</code>，但也有其他描述，仍然适用槽位限制条件。</p> <figure><img src="'+d+'" alt="" tabindex="0"><figcaption></figcaption></figure> <p><code>check</code> 参数还可填入 <code>STARTS_WITH</code> 和 <code>ENDS_WITH</code> 参数，分别表示检查物品中是否包含以给定内容开头或结尾的描述。</p> ',16)),t(a),t(c)])}const N=i(l,[["render",m]]);export{M as __pageData,N as default};
